import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideRouter } from '@angular/router';
import { routes } from './app.routes';

// The app's wiring: the router and the HTTP client.
export const appConfig: ApplicationConfig = {
  providers: [provideBrowserGlobalErrorListeners(), provideRouter(routes), provideHttpClient()],
};
import { Routes } from '@angular/router';

// The route table. A page is a new component file registered here with one entry that lazily
// imports it; an entry's `data: { section, label }` is read by the shell to build the nav bar.
export const routes: Routes = [
  { path: '', redirectTo: 'home', pathMatch: 'full' },
  {
    path: 'home',
    data: { section: 'home', label: 'Home', order: 0 },
    loadComponent: () => import('./features/home/home').then((m) => m.Home),
  },
  {
    path: 'clients',
    data: { section: 'clients', label: 'Clients', order: 1 },
    loadComponent: () => import('./features/clients/clients').then((m) => m.Clients),
  },
];
import { Component, inject } from '@angular/core';
import { Route, Router, RouterLink, RouterOutlet } from '@angular/router';

// Minimal base shell. It renders the nav bar and the routed page. The nav comes from the ROUTER'S
// OWN CONFIG — every route carrying `data.section` becomes a link — so the shell holds no list of
// pages and is not edited when one is added. Every observable element carries a stable data-testid.
@Component({
  selector: 'app-root',
  imports: [RouterOutlet, RouterLink],
  template: `
    <div data-testid="app-root">
      <nav data-testid="app-nav">
        @for (r of nav; track r.path) {
          <a
            [routerLink]="'/' + r.path"
            [attr.data-testid]="'nav-' + r.data!['section']"
            >{{ r.data!['label'] }}</a
          >
        }
      </nav>
      <main data-testid="app-home">
        <router-outlet />
      </main>
    </div>
  `,
})
export class App {
  protected readonly nav: Route[] = inject(Router)
    .config.filter((r) => !!r.data?.['section'])
    .sort(
      (a, b) =>
        ((a.data?.['order'] as number) ?? 0) - ((b.data?.['order'] as number) ?? 0) ||
        String(a.data?.['section']).localeCompare(String(b.data?.['section'])),
    );
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export interface Client {
  id: number;
  name: string;
  email: string;
}

export type NewClient = Omit<Client, 'id'>;

@Injectable({ providedIn: 'root' })
export class ClientService {
  private readonly http = inject(HttpClient);

  list(): Observable<Client[]> {
    return this.http.get<Client[]>('/api/clients');
  }

  create(client: NewClient): Observable<Client> {
    return this.http.post<Client>('/api/clients', client);
  }
}
import { Component, inject, signal } from '@angular/core';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { Client, ClientService } from './client.service';

// Clients page: add a client (name + email) and list all clients.
@Component({
  selector: 'app-clients',
  imports: [ReactiveFormsModule],
  template: `
    <h1>Clients</h1>

    <form [formGroup]="form" (ngSubmit)="submit()" data-testid="client-form" novalidate>
      <div>
        <label for="client-name">Name</label>
        <input
          id="client-name"
          type="text"
          formControlName="name"
          autocomplete="organization"
          data-testid="client-form-name"
          [attr.aria-invalid]="showError('name')"
          [attr.aria-describedby]="showError('name') ? 'client-name-error' : null"
        />
        @if (showError('name')) {
          <p id="client-name-error" role="alert" data-testid="client-form-name-error">
            Name is required.
          </p>
        }
      </div>
      <div>
        <label for="client-email">Email</label>
        <input
          id="client-email"
          type="email"
          formControlName="email"
          autocomplete="email"
          data-testid="client-form-email"
          [attr.aria-invalid]="showError('email')"
          [attr.aria-describedby]="showError('email') ? 'client-email-error' : null"
        />
        @if (showError('email')) {
          <p id="client-email-error" role="alert" data-testid="client-form-email-error">
            Enter a valid email address.
          </p>
        }
      </div>
      <button type="submit" data-testid="client-form-submit" [disabled]="saving()">Add client</button>
      @if (saveError()) {
        <p role="alert" data-testid="client-form-error">{{ saveError() }}</p>
      }
    </form>

    @if (clients().length === 0) {
      <p data-testid="clients-empty">No clients yet.</p>
    } @else {
      <table data-testid="clients-table">
        <caption>All clients</caption>
        <thead>
          <tr>
            <th scope="col">Name</th>
            <th scope="col">Email</th>
          </tr>
        </thead>
        <tbody>
          @for (c of clients(); track c.id) {
            <tr [attr.data-testid]="'client-row-' + c.id">
              <td data-testid="client-name">{{ c.name }}</td>
              <td data-testid="client-email">{{ c.email }}</td>
            </tr>
          }
        </tbody>
      </table>
    }
  `,
})
export class Clients {
  private readonly service = inject(ClientService);

  protected readonly clients = signal<Client[]>([]);
  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    name: ['', [Validators.required, Validators.maxLength(255)]],
    email: [
      '',
      [
        Validators.required,
        Validators.email,
        // Validators.email accepts "a@b"; also require a dotted domain (matches the server rule).
        Validators.pattern(/^[^@\s]+@[^@\s]+\.[^@\s]+$/),
        Validators.maxLength(255),
      ],
    ],
  });

  constructor() {
    this.load();
  }

  protected showError(field: 'name' | 'email'): boolean {
    const control = this.form.controls[field];
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    const { name, email } = this.form.getRawValue();
    this.saving.set(true);
    this.saveError.set(null);
    this.service.create({ name: name.trim(), email: email.trim() }).subscribe({
      next: (created) => {
        this.clients.update((list) => [...list, created]);
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not save the client. Please try again.');
        this.saving.set(false);
      },
    });
  }

  private load(): void {
    this.service.list().subscribe((list) => this.clients.set(list));
  }
}
